INSERT INTO _migration_463_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_env_b002_009', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'After an algal bloom dies in a polluted lake, fish often die in large numbers mainly because', 'multiple_choice', NULL, '["A. bacteria decomposing the dead algae use up the dissolved oxygen, so the fish suffocate","B. the dead algae release chlorine into the water","C. the algae physically trap the fish in thick mats","D. the water becomes too clear for fish to hide"]', 'A', 'Dead algae are decomposed by aerobic bacteria whose multiplication consumes dissolved oxygen faster than it is replaced, so the water becomes hypoxic and fish die of suffocation. Algae do not release chlorine, and physical entrapment or water clarity are not the cause of the mass deaths. Therefore the correct answer is A: bacteria decomposing the dead algae use up the dissolved oxygen, so the fish suffocate.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_env_b002_010', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Hard water does not lather easily with soap because it contains dissolved', 'multiple_choice', NULL, '["A. sodium chloride crystals","B. calcium and magnesium ions","C. chlorine gas","D. nitrate fertilizers only"]', 'B', 'Dissolved calcium and magnesium ions react with soap to form an insoluble scum instead of lather, wasting soap; boiling removes temporary hardness and washing soda or ion exchange removes permanent hardness. Sodium chloride, chlorine and nitrates do not cause hardness. Therefore the correct answer is B: calcium and magnesium ions.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_env_b002_011', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A water treatment plant doses water with 0.5 mg of chlorine per litre. Calculate the mass of chlorine, in grams, needed to treat 20 000 litres of water.', 'calculation', NULL, NULL, '10 g', 'Mass of chlorine = dose x volume = 0.5 mg per litre x 20 000 litres = 10 000 mg. Converting to grams: 10 000 mg / 1 000 = 10 g of chlorine.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_012', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A household uses 150 litres of water per day. Calculate the total volume of water the household uses in June (30 days), and the cost if the water company charges GHS 0.02 per litre.', 'calculation', NULL, NULL, '4 500 litres; GHS 90', 'Volume for June = 150 litres x 30 days = 4 500 litres. Cost = 4 500 litres x GHS 0.02 per litre = GHS 90.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_013', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A family in a rural community collects its drinking water from a river. Describe how the family can make the water safe for drinking and keep it safe during storage.', 'structured', NULL, NULL, '(a) Allow the water to stand so the heavy particles settle, decant the clearer water, then filter it through a clean cloth or a sand filter to remove the remaining suspended particles. (b) Boil the filtered water for several minutes so that the heat kills bacteria, viruses and parasite cysts; alternatively add the correct dose of chlorine tablets and wait the recommended time before drinking. (c) Keep the water in a clean container with a tight cover, and draw it with a clean ladle or tap rather than dipping cups or hands into it; store the container off the ground and away from animals and chemicals.', '(a) Allow the water to stand so the heavy particles settle, decant the clearer water, then filter it through a clean cloth or a sand filter to remove the remaining suspended particles. (b) Boil the filtered water for several minutes so that the heat kills bacteria, viruses and parasite cysts; alternatively add the correct dose of chlorine tablets and wait the recommended time before drinking. (c) Keep the water in a clean container with a tight cover, and draw it with a clean ladle or tap rather than dipping cups or hands into it; store the container off the ground and away from animals and chemicals.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_463_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_env_b002_013_a', 'q_wisc_env_b002_013', 'a', 'Describe how the family can remove the suspended particles from the river water.', '2', 'Allow the water to stand so the heavy particles settle, decant the clearer water, then filter it through a clean cloth or a sand filter to remove the remaining suspended particles.', '1'),
('sqp_q_wisc_env_b002_013_b', 'q_wisc_env_b002_013', 'b', 'Describe one method the family can use to kill the germs in the filtered water.', '2', 'Boil the filtered water for several minutes so that the heat kills bacteria, viruses and parasite cysts; alternatively add the correct dose of chlorine tablets and wait the recommended time before drinking.', '2'),
('sqp_q_wisc_env_b002_013_c', 'q_wisc_env_b002_013', 'c', 'State two precautions the family should take when storing the treated water.', '2', 'Keep the water in a clean container with a tight cover, and draw it with a clean ladle or tap rather than dipping cups or hands into it; store the container off the ground and away from animals and chemicals.', '3');
INSERT INTO _migration_463_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_463_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_463_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_463_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_463_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_463_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_463_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_463_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_463_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 5 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_463_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_463_expected e ON e.id = q.id) = 5 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_463_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
